export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await getManageableMember(actor, input);
  if (member.status === "suspended") return member;
  if (member.userId === actor.userId) throw new Error("You cannot suspend yourself");
  if (!hasRoleAtLeast(actor.role, member.role)) throw new Error(`A ${actor.role} cannot suspend a ${member.role}`);
  await assertLastActiveOwnerRetained(input.orgId, member);
  const updated = await memberRepo.setMemberStatus(input.orgId, input.memberId, "suspended");
  await emit("member.suspended", { ...actorEnvelope(actor), memberId: updated.id, userId: updated.userId });
  return updated;
}

export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await getManageableMember(actor, input);
  if (member.status === "active") return member;
  if (member.userId === actor.userId) throw new Error("You cannot reinstate yourself");
  if (!hasRoleAtLeast(actor.role, member.role)) throw new Error(`A ${actor.role} cannot reinstate a ${member.role}`);
  const updated = await memberRepo.setMemberStatus(input.orgId, input.memberId, "active");
  await emit("member.reinstated", { ...actorEnvelope(actor), memberId: updated.id, userId: updated.userId });
  return updated;
}

async function getManageableMember(actor: Actor, input: { orgId: OrgId; memberId: MemberId }): Promise<Member> {
  assertOrgScope(actor, input.orgId);
  const member = requireFound(await memberRepo.findMemberById(input.orgId, input.memberId), "Member", input.memberId);
  if (member.archivedAt !== null) throw new NotFoundError("Member", input.memberId);
  assertCan(actor, "member:remove", memberResource(member));
  return member;
}

async function assertLastActiveOwnerRetained(orgId: OrgId, member: Member): Promise<void> {
  if (member.role !== "owner") return;
  const owners = await memberRepo.listMembers({ orgId, role: "owner", status: "active", limit: OWNER_SCAN_LIMIT, cursor: null });
  if (owners.items.length <= 1) throw new Error("An organization must keep at least one active owner");
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because both the demote and the remove path need
 * it, and the invariant must not be stated twice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    status: "active",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}
